-- V2: core retail banking domain.
-- Conventions: money NUMERIC(19,2); rates as decimal fractions (0.0350 = 3.50%); enums as VARCHAR + CHECK;
-- dates in the bank's business calendar as DATE, event instants as TIMESTAMPTZ (UTC).
-- IDs use GENERATED BY DEFAULT so bulk loaders (the synthetic generator) may supply explicit ids.

CREATE TABLE customer (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    age                INTEGER        NOT NULL CHECK (age BETWEEN 18 AND 100),
    city               VARCHAR(32)    NOT NULL,
    occupation_group   VARCHAR(32)    NOT NULL,
    segment            VARCHAR(16)    NOT NULL
        CHECK (segment IN ('STUDENT', 'MIN_WAGE', 'WHITE_COLLAR', 'RETIREE', 'SELF_EMPLOYED')),
    -- Latest known monthly net income in TRY.
    monthly_net_income NUMERIC(19, 2) NOT NULL CHECK (monthly_net_income >= 0),
    customer_since     DATE           NOT NULL,
    status             VARCHAR(16)    NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'CHURNED', 'DEFAULTED'))
);

CREATE INDEX idx_customer_segment ON customer (segment);

CREATE TABLE account (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id   BIGINT         NOT NULL REFERENCES customer (id),
    account_type  VARCHAR(16)    NOT NULL CHECK (account_type IN ('CHECKING', 'TIME_DEPOSIT', 'CREDIT_CARD')),
    currency      VARCHAR(3)     NOT NULL CHECK (currency IN ('TRY', 'USD')),
    -- Funds for deposit accounts; outstanding debt (positive) for credit cards.
    balance       NUMERIC(19, 2) NOT NULL DEFAULT 0,
    opened_at     DATE           NOT NULL,
    closed_at     DATE,
    -- Time deposit only.
    interest_rate NUMERIC(9, 6),
    maturity_date DATE,
    -- Credit card only.
    credit_limit  NUMERIC(19, 2),
    statement_day INTEGER CHECK (statement_day BETWEEN 1 AND 28),
    due_day       INTEGER CHECK (due_day BETWEEN 1 AND 31),
    CONSTRAINT chk_account_card_fields CHECK (
        (account_type = 'CREDIT_CARD') = (credit_limit IS NOT NULL AND statement_day IS NOT NULL AND due_day IS NOT NULL)),
    CONSTRAINT chk_account_deposit_fields CHECK (
        (account_type = 'TIME_DEPOSIT') = (interest_rate IS NOT NULL AND maturity_date IS NOT NULL)),
    CONSTRAINT chk_account_card_currency CHECK (account_type <> 'CREDIT_CARD' OR currency = 'TRY'),
    CONSTRAINT chk_account_closed_after_open CHECK (closed_at IS NULL OR closed_at >= opened_at)
);

CREATE INDEX idx_account_customer ON account (customer_id);

CREATE TABLE card_statement (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id        BIGINT         NOT NULL REFERENCES account (id),
    statement_date    DATE           NOT NULL,
    due_date          DATE           NOT NULL,
    statement_balance NUMERIC(19, 2) NOT NULL CHECK (statement_balance >= 0),
    minimum_payment   NUMERIC(19, 2) NOT NULL CHECK (minimum_payment >= 0),
    paid_amount       NUMERIC(19, 2) NOT NULL DEFAULT 0 CHECK (paid_amount >= 0),
    paid_at           DATE,
    days_past_due     INTEGER        NOT NULL DEFAULT 0 CHECK (days_past_due >= 0),
    CONSTRAINT uq_card_statement UNIQUE (account_id, statement_date),
    CONSTRAINT chk_card_statement_due CHECK (due_date > statement_date)
);

CREATE TABLE loan (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id           BIGINT         NOT NULL REFERENCES customer (id),
    loan_type             VARCHAR(16)    NOT NULL CHECK (loan_type IN ('PERSONAL', 'MORTGAGE')),
    principal             NUMERIC(19, 2) NOT NULL CHECK (principal > 0),
    -- Turkish retail loans are quoted with a monthly contractual rate.
    monthly_interest_rate NUMERIC(9, 6)  NOT NULL CHECK (monthly_interest_rate >= 0),
    term_months           INTEGER        NOT NULL CHECK (term_months > 0),
    disbursed_at          DATE           NOT NULL,
    status                VARCHAR(16)    NOT NULL CHECK (status IN ('ACTIVE', 'CLOSED', 'DEFAULTED'))
);

CREATE INDEX idx_loan_customer ON loan (customer_id);

CREATE TABLE loan_installment (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    loan_id             BIGINT         NOT NULL REFERENCES loan (id),
    installment_no      INTEGER        NOT NULL CHECK (installment_no > 0),
    due_date            DATE           NOT NULL,
    principal_amount    NUMERIC(19, 2) NOT NULL CHECK (principal_amount >= 0),
    interest_amount     NUMERIC(19, 2) NOT NULL CHECK (interest_amount >= 0),
    total_amount        NUMERIC(19, 2) NOT NULL CHECK (total_amount >= 0),
    remaining_principal NUMERIC(19, 2) NOT NULL CHECK (remaining_principal >= 0),
    paid_amount         NUMERIC(19, 2) NOT NULL DEFAULT 0 CHECK (paid_amount >= 0),
    paid_at             DATE,
    days_past_due       INTEGER        NOT NULL DEFAULT 0 CHECK (days_past_due >= 0),
    CONSTRAINT uq_loan_installment UNIQUE (loan_id, installment_no),
    CONSTRAINT chk_loan_installment_total CHECK (total_amount = principal_amount + interest_amount)
);

CREATE INDEX idx_loan_installment_due_date ON loan_installment (due_date);

CREATE TABLE merchant_category (
    id   INTEGER PRIMARY KEY,
    code VARCHAR(32) NOT NULL UNIQUE,
    name VARCHAR(64) NOT NULL
);

CREATE TABLE merchant (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(64) NOT NULL,
    category_id INTEGER     NOT NULL REFERENCES merchant_category (id),
    city        VARCHAR(32) NOT NULL
);

CREATE INDEX idx_merchant_category ON merchant (category_id);

-- "transaction" is an SQL keyword, hence bank_transaction.
CREATE TABLE bank_transaction (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id        BIGINT         NOT NULL REFERENCES account (id),
    -- Denormalised owner for per-customer time-range queries without joining account.
    customer_id       BIGINT         NOT NULL REFERENCES customer (id),
    merchant_id       BIGINT REFERENCES merchant (id),
    amount            NUMERIC(19, 2) NOT NULL CHECK (amount > 0),
    currency          VARCHAR(3)     NOT NULL CHECK (currency IN ('TRY', 'USD')),
    direction         VARCHAR(8)     NOT NULL CHECK (direction IN ('DEBIT', 'CREDIT')),
    channel           VARCHAR(16)    NOT NULL
        CHECK (channel IN ('POS', 'ECOMMERCE', 'ATM', 'EFT_FAST', 'AUTO_PAYMENT')),
    installment_count INTEGER        NOT NULL DEFAULT 1 CHECK (installment_count BETWEEN 1 AND 36),
    raw_description   VARCHAR(128)   NOT NULL,
    occurred_at       TIMESTAMPTZ    NOT NULL
);

CREATE INDEX idx_bank_transaction_customer_time ON bank_transaction (customer_id, occurred_at);
CREATE INDEX idx_bank_transaction_account_time ON bank_transaction (account_id, occurred_at);
CREATE INDEX idx_bank_transaction_merchant ON bank_transaction (merchant_id);

CREATE TABLE customer_event (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id   BIGINT      NOT NULL REFERENCES customer (id),
    event_type    VARCHAR(16) NOT NULL CHECK (event_type IN ('LATE_PAYMENT', 'DEFAULT', 'CHURN')),
    event_date    DATE        NOT NULL,
    account_id    BIGINT REFERENCES account (id),
    loan_id       BIGINT REFERENCES loan (id),
    days_past_due INTEGER CHECK (days_past_due >= 0),
    details       VARCHAR(255)
);

CREATE INDEX idx_customer_event_customer_type ON customer_event (customer_id, event_type);
CREATE INDEX idx_customer_event_type_date ON customer_event (event_type, event_date);

CREATE TABLE macro_indicator (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    indicator VARCHAR(32)    NOT NULL CHECK (indicator IN ('MONTHLY_INFLATION', 'POLICY_RATE', 'USD_TRY')),
    -- First day of the month the value refers to.
    period    DATE           NOT NULL CHECK (EXTRACT(DAY FROM period) = 1),
    value     NUMERIC(12, 4) NOT NULL,
    source    VARCHAR(16)    NOT NULL,
    CONSTRAINT uq_macro_indicator UNIQUE (indicator, period)
);
